"use client"

/** @responsibility Renders one closing ring per metric — concentric tracks or goal-weighted segments of one track — that sweep up from empty on mount and ease to every later reading, with an optional centred readout and optional hover isolation. Geometry comes from activity-rings-geometry. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  activityRingTrackPath,
  computeActivityRingsLayout,
  type ActivityRingsArrangement,
  type ActivityRingsLayout,
  type ActivityRingsLayoutIssue,
  type ActivityRingsLayoutRing,
} from "./activity-rings-geometry"

/** One metric's progress toward its goal. */
export interface ActivityRing {
  /** Unique id. */
  id: string
  /** Name used in readouts and legends. Defaults to the id. */
  label?: string
  /**
   * How much has been done. A reading past the goal is not clamped: a
   * concentric ring laps its track, and a segment fills its own span.
   */
  value: number
  /**
   * What counts as complete. Must be positive. In the "segmented"
   * arrangement the goal also sets the segment's share of the circle, so
   * goals there must share one unit.
   */
  goal: number
  /**
   * Optional CSS color for the band. Omitted, rings cycle through the
   * component's `palette`.
   */
  color?: string
  /**
   * Optional CSS color for text that names this ring in a legend. Omitted,
   * rings take the matching slot of `activityRingsInkPalette`. Set it
   * alongside `color` whenever a custom band colour is too light to read as
   * text on the card's own surface.
   */
  ink?: string
  /** Unit appended to a reading, such as "CAL". Used by legends. */
  unit?: string
  /**
   * Secondary line a legend may show under the ring's name, such as
   * "34m later than average". Ignored by the rings themselves.
   */
  detail?: React.ReactNode
}

/**
 * The closing-ring trio, in the register people already read as activity:
 * energy, effort, uprightness. It is a named set of roles rather than three
 * slots borrowed from the categorical chart ramp, for the same reason the
 * market gain/loss pair has its own tokens — a ring set means one thing
 * wherever it appears. Past the third ring the palette continues into the
 * categorical ramp's solid step, which is the right answer for a set that
 * has stopped being the canonical three.
 *
 * Rings take a slot in input order and a slot always names the same metric,
 * so a reading that overtakes another never repaints the rings around it.
 */
export const activityRingsPalette: readonly string[] = Object.freeze([
  "var(--nessa-activity-ring-1)",
  "var(--nessa-activity-ring-2)",
  "var(--nessa-activity-ring-3)",
  "var(--nessa-chart-series-4-strong)",
  "var(--nessa-chart-series-5-strong)",
  "var(--nessa-chart-series-6-strong)",
  "var(--nessa-chart-series-7-strong)",
  "var(--nessa-chart-series-8-strong)",
])

/**
 * The ink a legend writes a ring's name in, slot for slot with
 * `activityRingsPalette`. A band is a graphical mark, held to the 3:1
 * non-text floor against its own track; the same colour set as text misses
 * the 4.5:1 one, and a lime ring's own value would be unreadable on a white
 * card. Each ink is the deepest hue-true version of its band that clears
 * text contrast, so a legend row still reads as the ring it names.
 *
 * The categorical ramp has no such step — it is a fill/edge pair, both
 * marks — so slots past the trio fall back to the surface's own foreground.
 */
export const activityRingsInkPalette: readonly (string | null)[] = Object.freeze([
  "var(--nessa-activity-ring-1-ink)",
  "var(--nessa-activity-ring-2-ink)",
  "var(--nessa-activity-ring-3-ink)",
  null,
  null,
  null,
  null,
  null,
])

/** Everything known about one ring when a readout or legend row is rendered. */
export interface ActivityRingContext {
  /** The input row. */
  ring: ActivityRing
  /** Index into the original `rings` input. */
  index: number
  /** The reading, clamped to zero at the bottom. */
  value: number
  goal: number
  /** `value / goal`, never clamped at the top. */
  progress: number
  /** Whole times the ring has been round its track. */
  laps: number
  /** The tint the band is drawn with, when the ring carries one. */
  color?: string
}

/** What the centred readout is asked to render. */
export interface ActivityRingsCenterContext {
  /** Every drawn ring, in input order. */
  rings: ActivityRingContext[]
  /** The ring currently hovered, or null at rest. */
  active: ActivityRingContext | null
  /**
   * Mean progress across the rings with each one capped at its own goal,
   * 0..1 — the "how close is the whole set to closed" reading. Beating one
   * goal cannot make up for missing another.
   */
  completion: number
}

/** Emphasis a band is drawn with. */
type ActivityRingEmphasis = "rest" | "active" | "dim"

/** Properties accepted by ActivityRings. */
export interface ActivityRingsProps extends React.ComponentProps<"div"> {
  rings: readonly ActivityRing[]
  /**
   * How the rings are placed. "concentric" (default) nests one full circle
   * per ring, outside-in in input order, and lets a ring lap its track.
   * "segmented" splits one circle between them, each taking a share of the
   * sweep proportional to its goal.
   */
  arrangement?: ActivityRingsArrangement
  /**
   * Band width, in pixels. Left out, it scales with the box the rings fill,
   * so a set reads the same at any size — which is what a host wants unless
   * it is matching a band to something else on the page.
   */
  thickness?: number
  /**
   * Gap between neighbouring concentric tracks, in pixels. Left out, it is a
   * fraction of the band width, so the tracks stay tight against each other
   * as the band grows.
   */
  ringGap?: number
  /** Gap between neighbouring segments, in degrees. Segmented only. */
  segmentGap?: number
  /** Where the tracks start, in degrees clockwise from straight up. */
  startAngle?: number
  /** Opacity of the unfilled track behind each band, 0..1. */
  trackOpacity?: number
  /**
   * Tints rings cycle through in input order; a ring's own `color` wins.
   * Pass null for an all-neutral set, which then needs another way to tell
   * the rings apart.
   */
  palette?: readonly string[] | null
  /**
   * Sweeps the bands up from empty on first paint. Turn it off for a ring
   * that is already on screen when its host mounts, such as one inside a
   * list that virtualises. The sweep runs on Nessa's motion duration tokens,
   * so `prefers-reduced-motion` removes it without any host involvement.
   */
  animateOnMount?: boolean
  /**
   * Recedes every other ring while one is hovered. Off by default: bare
   * rings are a summary, not a control. Hosts that pair the rings with a
   * legend — ActivityRingsCard does — turn it on and mirror the highlight.
   */
  highlightOnHover?: boolean
  /** Controlled highlighted ring, or null for none. */
  activeRingId?: string | null
  /** Initial highlight when uncontrolled. */
  defaultActiveRingId?: string | null
  /** Called as the highlight moves, with null when it clears. */
  onActiveRingChange?: (
    ringId: string | null,
    context: ActivityRingContext | null,
  ) => void
  /** Formats a reading wherever one is shown. */
  formatValue?: (value: number, ring: ActivityRing) => string
  /**
   * Content for the middle of the rings. Nothing is drawn there by default —
   * a bare ring set carries no derived headline of its own.
   */
  renderCenter?: (context: ActivityRingsCenterContext) => React.ReactNode
  /**
   * The sentence one ring contributes to the off-screen reading. Defaults to
   * "Move: 450 of 800 CAL, 56 percent".
   */
  ringDescription?: (context: ActivityRingContext) => string
  /**
   * Called whenever the set of tolerated data problems changes — a dropped
   * ring, a negative reading read as zero, a ring with no room left at this
   * size — and once after the first layout to establish the initial state.
   * While data streams in, transient issues come and go; once the stream
   * settles, an empty array is the definitive "everything rendered" signal
   * and anything else is a data error worth surfacing.
   */
  onLayoutIssues?: (issues: ActivityRingsLayoutIssue[]) => void
  /**
   * Renders the off-screen list of readings that carries the rings to a
   * screen reader. Turn it off in a host that already writes the same
   * numbers as text — ActivityRingsCard does — so they are not announced
   * twice.
   */
  describeValues?: boolean
}

function useMeasuredBox(ref: React.RefObject<HTMLElement | null>) {
  const [box, setBox] = React.useState<{ width: number; height: number } | null>(
    null,
  )
  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      const rect = entries[entries.length - 1].contentRect
      const width = Math.round(rect.width)
      const height = Math.round(rect.height)
      setBox((previous) =>
        previous && previous.width === width && previous.height === height
          ? previous
          : { width, height },
      )
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
  return box
}

/**
 * True once the browser has painted at least one frame, so a value change
 * transitions instead of arriving finished. Two frames are needed, not one:
 * the empty state has to reach the screen before the target replaces it.
 */
function useAfterFirstPaint(enabled: boolean) {
  const [painted, setPainted] = React.useState(!enabled)
  React.useEffect(() => {
    if (!enabled) return
    let inner = 0
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setPainted(true))
    })
    return () => {
      cancelAnimationFrame(outer)
      cancelAnimationFrame(inner)
    }
  }, [enabled])
  return painted
}

const BAND_CLASSES = cn(
  "fill-none stroke-[var(--nessa-activity-ring-color,var(--muted-foreground))]",
  // `stroke-dashoffset` and `d` are transitionable presentation attributes, so
  // the sweep and every later reading animate without a JavaScript loop.
  "transition-[stroke-dashoffset,d] [transition-timing-function:var(--nessa-motion-easing-arrival)]",
  // A ring sweeps a whole circle, not a few pixels, so it is paced at a
  // multiple of the slow token rather than at the token itself — derived from
  // it, so `prefers-reduced-motion` still collapses the sweep to nothing.
  "[transition-duration:calc(var(--nessa-motion-duration-slow)*var(--nessa-activity-ring-sweep-steps))] [transition-delay:var(--nessa-activity-ring-delay)]",
  "motion-reduce:transition-none",
)

/**
 * Emphasis is carried by the group rather than the bands, because each band
 * already sets its own opacity — the track's wash, the completed lap's
 * recession — and a class on the band would replace those readings instead of
 * receding them.
 */
const SHADOW_CLASSES = cn(
  "transition-transform [transition-timing-function:var(--nessa-motion-easing-arrival)]",
  "[transition-duration:calc(var(--nessa-motion-duration-slow)*var(--nessa-activity-ring-sweep-steps))] [transition-delay:var(--nessa-activity-ring-delay)]",
  "motion-reduce:transition-none",
)

const RING_GROUP_CLASSES = cn(
  "transition-opacity [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=dim]:opacity-25",
)

/**
 * How many of the slow token's steps one ring's sweep takes. A ring travels a
 * whole circle, not a few pixels, so it is paced at a multiple of the token
 * rather than at the token itself — still derived from it, so
 * `prefers-reduced-motion` collapses the sweep to nothing.
 */
const SWEEP_STEPS = 3

/**
 * Band width as a fraction of the box's shorter edge, and the gap between
 * tracks as a fraction of that band. Both are proportions rather than pixel
 * defaults because a ring set is read as one object: a band that keeps its
 * pixel width while the figure grows stops looking like the same thing.
 */
const BAND_FRACTION = 0.122
const RING_GAP_FRACTION = 0.18

/**
 * How much of one sweep each ring waits before starting, so a set closes
 * outside-in rather than all at once.
 */
const STAGGER_FRACTION = 0.15

/**
 * How far the leading cap's shadow is thrown ahead of the cap, and how soft
 * it is, as fractions of the band's width. The completed lap stays at full
 * strength — it was completed — so this shadow is the only thing separating a
 * ring at 100% from one at 200%, both of which are a closed circle.
 */
const CAP_SHADOW_THROW = 0.32
const CAP_SHADOW_BLUR = 0.22

/**
 * Concentric activity rings, or one ring split into goal-weighted segments:
 * a band per metric, swept up from empty on mount and eased to every later
 * reading. A concentric ring that beats its goal laps its own track, drawing
 * the completed lap behind the leading arc; a segment fills its own span and
 * stops. Rings take a slot from the design system's categorical ramp in input
 * order, so a slot always names the same metric.
 *
 * The bands are decoration: the readings reach a screen reader as an
 * off-screen list, which a host already writing the same numbers as text can
 * turn off with `describeValues`. Name the set through `aria-label`.
 */
function ActivityRings({
  rings,
  arrangement = "concentric",
  thickness,
  ringGap,
  segmentGap = 6,
  startAngle = 0,
  trackOpacity = 0.2,
  palette = activityRingsPalette,
  animateOnMount = true,
  highlightOnHover = false,
  activeRingId,
  defaultActiveRingId = null,
  onActiveRingChange,
  formatValue = (value) => String(value),
  renderCenter,
  ringDescription,
  onLayoutIssues,
  describeValues = true,
  className,
  ...props
}: ActivityRingsProps) {
  const plotRef = React.useRef<HTMLDivElement>(null)
  const box = useMeasuredBox(plotRef)
  const painted = useAfterFirstPaint(animateOnMount)
  // Filter ids are document-global, so two ring sets on one page would share
  // one blur if the id were a constant.
  const shadowFilterId = `${React.useId()}-activity-ring-cap-shadow`

  const [uncontrolledActive, setUncontrolledActive] = React.useState<
    string | null
  >(defaultActiveRingId)
  const active = activeRingId !== undefined ? activeRingId : uncontrolledActive

  // Duplicate ids keep their FIRST occurrence, matching the geometry's own
  // dedupe — the tint and the reading must describe the row the band was
  // struck from.
  const uniqueRings = React.useMemo(() => {
    const seen = new Set<string>()
    const result: ActivityRing[] = []
    for (const ring of rings) {
      if (seen.has(ring.id)) continue
      seen.add(ring.id)
      result.push(ring)
    }
    return result
  }, [rings])
  const ringById = React.useMemo(
    () => new Map(uniqueRings.map((ring) => [ring.id, ring])),
    [uniqueRings],
  )

  const layout: ActivityRingsLayout | null = React.useMemo(() => {
    if (!box || box.width <= 0 || box.height <= 0) return null
    const band =
      thickness ?? Math.min(box.width, box.height) * BAND_FRACTION
    return computeActivityRingsLayout({
      rings,
      width: box.width,
      height: box.height,
      arrangement,
      thickness: band,
      ringGap: ringGap ?? band * RING_GAP_FRACTION,
      segmentGap,
      startAngle,
    })
  }, [box, rings, arrangement, thickness, ringGap, segmentGap, startAngle])

  // Rings take their slot in INPUT order, never laid-out order: a slot names
  // an entity, so a reading that overtakes another must not repaint it.
  const colorOf = React.useMemo(() => {
    const colors = new Map<string, string>()
    if (!palette || palette.length === 0) {
      for (const ring of uniqueRings) {
        if (ring.color) colors.set(ring.id, ring.color)
      }
      return colors
    }
    uniqueRings.forEach((ring, index) => {
      colors.set(ring.id, ring.color ?? palette[index % palette.length])
    })
    return colors
  }, [uniqueRings, palette])

  const contextOf = React.useCallback(
    (laid: ActivityRingsLayoutRing): ActivityRingContext => ({
      ring: ringById.get(laid.id) ?? {
        id: laid.id,
        value: laid.value,
        goal: laid.goal,
      },
      index: laid.index,
      value: laid.value,
      goal: laid.goal,
      progress: laid.progress,
      laps: laid.laps,
      ...(colorOf.has(laid.id) ? { color: colorOf.get(laid.id) } : {}),
    }),
    [ringById, colorOf],
  )

  // The browser fires no pointerleave for an element removed from the DOM, so
  // a frame that drops the highlighted ring would leave its id behind — every
  // other band dimmed with nothing active. Whatever the layout no longer
  // contains is not active.
  const drawnIds = React.useMemo(
    () => new Set((layout?.rings ?? []).map((laid) => laid.id)),
    [layout],
  )
  const liveActive = active !== null && drawnIds.has(active) ? active : null
  const onActiveRingChangeRef = React.useRef(onActiveRingChange)
  onActiveRingChangeRef.current = onActiveRingChange
  React.useEffect(() => {
    if (active !== null && liveActive === null) {
      setUncontrolledActive(null)
      onActiveRingChangeRef.current?.(null, null)
    }
  }, [active, liveActive])

  const changeActive = (ringId: string | null, laid: ActivityRingsLayoutRing | null) => {
    if (activeRingId === undefined) setUncontrolledActive(ringId)
    onActiveRingChange?.(ringId, laid ? contextOf(laid) : null)
  }

  // Report tolerated data problems whenever their set changes — including the
  // change back to none, which is the "everything rendered" signal.
  const onLayoutIssuesRef = React.useRef(onLayoutIssues)
  onLayoutIssuesRef.current = onLayoutIssues
  const issuesKey = layout
    ? layout.issues
        .map((issue) => `${issue.kind}@${issue.ringId ?? ""}:${issue.message}`)
        .join("\n")
    : null
  React.useEffect(() => {
    if (issuesKey === null || !layout) return
    onLayoutIssuesRef.current?.(layout.issues)
    // The layout object changes identity on every resize; only a changed
    // issue set should re-notify.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [issuesKey])

  const emphasisOf = (id: string): ActivityRingEmphasis => {
    if (liveActive === null) return "rest"
    return liveActive === id ? "active" : "dim"
  }

  const ringContexts = React.useMemo(
    () =>
      [...(layout?.rings ?? [])]
        .sort((left, right) => left.index - right.index)
        .map(contextOf),
    [layout, contextOf],
  )

  const defaultRingDescription = (context: ActivityRingContext) => {
    const unit = context.ring.unit ? ` ${context.ring.unit}` : ""
    return `${context.ring.label ?? context.ring.id}: ${formatValue(context.value, context.ring)} of ${formatValue(context.goal, context.ring)}${unit}, ${Math.round(context.progress * 100)} percent`
  }

  const centerContent = renderCenter
    ? renderCenter({
        rings: ringContexts,
        active:
          liveActive === null
            ? null
            : (ringContexts.find((context) => context.ring.id === liveActive) ??
              null),
        completion: ringContexts.length
          ? ringContexts.reduce(
              (sum, context) => sum + Math.min(1, context.progress),
              0,
            ) / ringContexts.length
          : 0,
      })
    : null

  return (
    <div
      data-slot="activity-rings"
      // The host names the set through aria-label, which a role-less generic
      // element may not carry.
      role="group"
      className={cn(
        "relative flex h-full min-h-0 w-full min-w-0 font-sans text-foreground",
        className,
      )}
      {...props}
    >
      <div ref={plotRef} className="relative min-h-0 min-w-0 flex-1">
        {layout ? (
          <svg
            aria-hidden="true"
            className="absolute inset-0 size-full"
            width={box!.width}
            height={box!.height}
          >
            <defs>
              <filter
                id={shadowFilterId}
                x="-100%"
                y="-100%"
                width="300%"
                height="300%"
              >
                <feGaussianBlur
                  stdDeviation={layout.thickness * CAP_SHADOW_BLUR}
                />
              </filter>
            </defs>
            {layout.rings.map((laid, placement) => {
              const track = activityRingTrackPath(
                layout.cx,
                layout.cy,
                laid.radius,
                laid.trackStart,
                laid.trackEnd,
              )
              if (!track) return null
              const tint = colorOf.get(laid.id)
              const band = {
                d: track,
                strokeWidth: layout.thickness,
                strokeLinecap: "round",
                className: BAND_CLASSES,
                style: {
                  // Rings start their sweeps one after another, so a set
                  // closes outside-in. The stagger is expressed against the
                  // motion token, so reduced motion removes it with the sweep.
                  "--nessa-activity-ring-sweep-steps": String(SWEEP_STEPS),
                  "--nessa-activity-ring-delay": `calc(var(--nessa-motion-duration-slow) * ${(placement * STAGGER_FRACTION * SWEEP_STEPS).toFixed(3)})`,
                  ...(tint ? { "--nessa-activity-ring-color": tint } : {}),
                } as React.CSSProperties,
              } as const
              return (
                <g
                  key={laid.id}
                  data-slot="activity-rings-ring"
                  data-ring-id={laid.id}
                  data-emphasis={emphasisOf(laid.id)}
                  className={RING_GROUP_CLASSES}
                >
                  <path
                    data-slot="activity-rings-track"
                    {...band}
                    opacity={trackOpacity}
                  />
                  {laid.laps > 0 ? (
                    <path data-slot="activity-rings-lap" {...band} />
                  ) : null}
                  {laid.laps > 0 ? (
                    <g
                      data-slot="activity-rings-cap-shadow"
                      aria-hidden="true"
                      // Rotating the whole group carries the shadow along the
                      // arc, so it follows the cap round instead of cutting
                      // the chord a moving centre would take.
                      transform={`rotate(${(laid.capAngle * 180) / Math.PI} ${layout.cx} ${layout.cy})`}
                      className={SHADOW_CLASSES}
                      style={band.style}
                    >
                      <circle
                        cx={layout.cx + layout.thickness * CAP_SHADOW_THROW}
                        cy={layout.cy - laid.radius}
                        r={layout.thickness / 2}
                        fill="var(--nessa-activity-ring-cap-shadow)"
                        filter={`url(#${shadowFilterId})`}
                      />
                    </g>
                  ) : null}
                  <path
                    // A reading crossing a whole goal takes `fill` from near
                    // 1 back to near 0, and interpolating that would unwind
                    // the arc backwards to show ten percent more progress.
                    // Keying on the lap retires the finished arc and starts a
                    // fresh one, which is what a ring passing its goal
                    // actually does: it closes, and the next lap begins at the
                    // top. Readings inside one lap keep the same element and
                    // ease as before.
                    key={`band-${laid.laps}`}
                    data-slot="activity-rings-band"
                    data-ring-id={laid.id}
                    {...band}
                    // A metric at nothing draws nothing: a full-length dash
                    // pushed entirely off the path still leaves a hairline at
                    // the seam, and a round cap on it paints a whole dot — the
                    // same mark a ring just begun would show. A ring on its
                    // way somewhere keeps both, so its sweep starts from a dot.
                    strokeLinecap={laid.fill > 0 ? "round" : "butt"}
                    // Normalising the path to a length of 1 makes one dash
                    // pattern describe any arc, so the fill fraction is the
                    // dash offset whatever the radius or sweep.
                    pathLength={1}
                    strokeDasharray={laid.fill > 0 ? "1 1" : "0 1"}
                    strokeDashoffset={1 - (painted ? laid.fill : 0)}
                  />
                  {highlightOnHover ? (
                    <path
                      data-slot="activity-rings-target"
                      d={track}
                      strokeWidth={layout.thickness}
                      strokeLinecap="round"
                      // A transparent stroke is not hit by the default
                      // `visiblePainted`, so the band would never answer the
                      // pointer without naming the stroke as its hit area.
                      className="cursor-pointer fill-none stroke-transparent [pointer-events:stroke]"
                      onPointerEnter={() => changeActive(laid.id, laid)}
                      onPointerLeave={() => {
                        if (liveActive === laid.id) changeActive(null, null)
                      }}
                    />
                  ) : null}
                </g>
              )
            })}
          </svg>
        ) : null}
        {centerContent != null && layout ? (
          <div
            data-slot="activity-rings-center"
            className="pointer-events-none absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center text-center leading-tight"
            style={{
              left: layout.cx,
              top: layout.cy,
              maxWidth: layout.centerRadius * 2,
            }}
          >
            {centerContent}
          </div>
        ) : null}
      </div>
      {describeValues ? (
        <ul data-slot="activity-rings-readings" className="sr-only">
          {ringContexts.map((context) => (
            <li key={context.ring.id}>
              {(ringDescription ?? defaultRingDescription)(context)}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}

export { ActivityRings }

"use client"

/** @responsibility Pairs one figure — activity rings by default, any component on request — with a per-metric legend inside a Card, either beside the figure or listed beneath it, and keeps the highlight on the figure and its legend row in step. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../card"
import {
  ActivityRings,
  activityRingsInkPalette,
  activityRingsPalette,
  type ActivityRing,
  type ActivityRingContext,
  type ActivityRingsCenterContext,
} from "./activity-rings"
import type { ActivityRingsArrangement } from "./activity-rings-geometry"

/**
 * Where the legend sits. "beside" runs the readings down the right of the
 * figure, one compact pair each — the summary-tile form. "stacked" puts the
 * figure and the headline on top and lists the readings underneath as
 * separated rows, which is the form that has room for a second detail line
 * per metric.
 */
export type ActivityRingsCardLayout = "beside" | "stacked"

/** Properties accepted by ActivityRingsCard. */
export interface ActivityRingsCardProps
  extends Omit<React.ComponentProps<typeof Card>, "title"> {
  /** The metrics, in the order they take ring slots and legend rows. */
  rings: readonly ActivityRing[]
  /** Legend placement. Defaults to "beside". */
  layout?: ActivityRingsCardLayout
  /** Card headline. In the stacked layout it sits beside the figure. */
  title?: React.ReactNode
  /** Second line under the headline. */
  description?: React.ReactNode
  /** Control parked in the card's top corner, such as an info button. */
  action?: React.ReactNode
  /**
   * Replaces the rings with any component — a gauge, a sparkline, an avatar.
   * The legend still describes `rings`, so a figure that shows something else
   * entirely should come with a legend that says so.
   */
  figure?: React.ReactNode
  /**
   * Edge length of the square the figure fills, in pixels. The default rings
   * scale their bands to whatever box they are given, so this one number
   * sizes the whole figure.
   */
  figureSize?: number
  /** How the default rings are placed. Defaults to "concentric". */
  arrangement?: ActivityRingsArrangement
  /** Content for the middle of the default rings. */
  renderCenter?: (context: ActivityRingsCenterContext) => React.ReactNode
  /** Formats a reading wherever one is shown. */
  formatValue?: (value: number, ring: ActivityRing) => string
  /**
   * The row's right-hand readout. Defaults to "450/800 CAL" — the reading,
   * its goal, and the ring's unit.
   */
  renderReading?: (context: ActivityRingContext) => React.ReactNode
}

const ROW_CLASSES = cn(
  "flex min-w-0 flex-col transition-opacity [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=dim]:opacity-45",
)

/**
 * A Card that reads a set of metrics as one figure plus a legend: activity
 * rings on the left with their readings beside them, or the rings and a
 * headline on top with the readings listed underneath. Hovering a ring lifts
 * its legend row and recedes the others, and hovering a row does the same to
 * the rings, so the two halves always name the same metric.
 *
 * The figure is decoration here — the legend already writes every reading as
 * text — so the rings do not repeat themselves to a screen reader. Pass
 * `figure` to put any other component in the figure's place.
 */
function ActivityRingsCard({
  rings,
  layout = "beside",
  title,
  description,
  action,
  figure,
  figureSize = 132,
  arrangement = "concentric",
  renderCenter,
  formatValue = (value) => String(value),
  renderReading,
  className,
  ...props
}: ActivityRingsCardProps) {
  const [active, setActive] = React.useState<string | null>(null)

  // Rows take their tint the way the rings do — by input order, so the row
  // beside a name is the band that names it. The row writes in the ring's
  // INK, not its band colour: a band is a graphical mark held to the 3:1
  // non-text floor, and the same colour as text would miss the 4.5:1 one.
  const paintOf = React.useMemo(() => {
    const paints = new Map<string, { color?: string; ink?: string }>()
    const seen = new Set<string>()
    let slot = 0
    for (const ring of rings) {
      if (seen.has(ring.id)) continue
      seen.add(ring.id)
      const index = slot % activityRingsPalette.length
      const ink = ring.ink ?? activityRingsInkPalette[index]
      paints.set(ring.id, {
        color: ring.color ?? activityRingsPalette[index],
        ...(ink ? { ink } : {}),
      })
      slot += 1
    }
    return paints
  }, [rings])

  const rows = React.useMemo(() => {
    const seen = new Set<string>()
    const result: ActivityRingContext[] = []
    rings.forEach((ring, index) => {
      if (seen.has(ring.id)) return
      seen.add(ring.id)
      const value = Math.max(0, ring.value)
      const progress = ring.goal > 0 ? value / ring.goal : 0
      result.push({
        ring,
        index,
        value,
        goal: ring.goal,
        progress,
        // A segment cannot pass its own end, so only a concentric ring laps.
        // A goal met exactly reads as a closed ring, not a lap.
        laps:
          arrangement === "segmented"
            ? 0
            : Math.max(0, Math.ceil(progress) - 1),
        ...(paintOf.get(ring.id)?.color
          ? { color: paintOf.get(ring.id)!.color }
          : {}),
      })
    })
    return result
  }, [rings, paintOf, arrangement])

  const defaultReading = (context: ActivityRingContext) =>
    `${formatValue(context.value, context.ring)}/${formatValue(context.goal, context.ring)}${context.ring.unit ? ` ${context.ring.unit}` : ""}`

  const figureNode = figure ?? (
    <ActivityRings
      rings={rings}
      arrangement={arrangement}
      renderCenter={renderCenter}
      formatValue={formatValue}
      highlightOnHover
      activeRingId={active}
      onActiveRingChange={setActive}
      // The legend below writes every reading as text; announcing the rings
      // as well would read the same numbers twice.
      describeValues={false}
    />
  )

  const figureBox = (
    <div
      data-slot="activity-rings-card-figure"
      className="shrink-0"
      style={{ width: figureSize, height: figureSize }}
    >
      {figureNode}
    </div>
  )

  const emphasisOf = (id: string) =>
    active === null ? "rest" : active === id ? "active" : "dim"

  const rowHandlers = (id: string) => ({
    onPointerEnter: () => setActive(id),
    onPointerLeave: () =>
      setActive((previous) => (previous === id ? null : previous)),
  })

  const swatch = (context: ActivityRingContext) => (
    <span
      aria-hidden="true"
      className="size-2.5 shrink-0 rounded-full bg-[var(--nessa-activity-rings-row-color,var(--muted-foreground))]"
      style={
        context.color
          ? ({
              "--nessa-activity-rings-row-color": context.color,
            } as React.CSSProperties)
          : undefined
      }
    />
  )

  /** The ring's ink as a row-scoped custom property, when it carries one. */
  const inkStyle = (context: ActivityRingContext) => {
    const ink = paintOf.get(context.ring.id)?.ink
    return ink
      ? ({ "--nessa-activity-rings-row-ink": ink } as React.CSSProperties)
      : undefined
  }

  const reading = (context: ActivityRingContext) =>
    renderReading ? renderReading(context) : defaultReading(context)

  const header =
    title != null || description != null || action != null ? (
      <CardHeader>
        {title != null ? <CardTitle className="nessa-text-5">{title}</CardTitle> : null}
        {description != null ? <CardDescription>{description}</CardDescription> : null}
        {action != null ? <CardAction>{action}</CardAction> : null}
      </CardHeader>
    ) : null

  return (
    <Card
      data-slot="activity-rings-card"
      data-layout={layout}
      // The figure carries the card's weight, so the headline sits closer to
      // it than the Card's own six-step rhythm would put it.
      className={cn("gap-3", className)}
      {...props}
    >
      {layout === "beside" ? (
        <>
          {header}
          <CardContent className="flex items-center gap-5">
            {figureBox}
            <ul
              data-slot="activity-rings-card-legend"
              className="flex min-w-0 flex-1 flex-col gap-3"
            >
              {rows.map((context) => (
                <li
                  key={context.ring.id}
                  data-slot="activity-rings-card-row"
                  data-ring-id={context.ring.id}
                  data-emphasis={emphasisOf(context.ring.id)}
                  className={ROW_CLASSES}
                  style={inkStyle(context)}
                  {...rowHandlers(context.ring.id)}
                >
                  <span className="nessa-text-3 truncate text-muted-foreground">
                    {context.ring.label ?? context.ring.id}
                  </span>
                  <span className="nessa-text-4 truncate font-medium tabular-nums text-[var(--nessa-activity-rings-row-ink,var(--foreground))]">
                    {reading(context)}
                  </span>
                  {context.ring.detail != null ? (
                    <span className="nessa-text-2 truncate text-muted-foreground">
                      {context.ring.detail}
                    </span>
                  ) : null}
                </li>
              ))}
            </ul>
          </CardContent>
        </>
      ) : (
        <>
          <CardHeader>
            <div className="flex items-center gap-4">
              {figureBox}
              <div className="flex min-w-0 flex-col gap-1">
                {title != null ? (
                  <CardTitle className="nessa-text-7">{title}</CardTitle>
                ) : null}
                {description != null ? (
                  <CardDescription>{description}</CardDescription>
                ) : null}
              </div>
            </div>
            {action != null ? <CardAction>{action}</CardAction> : null}
          </CardHeader>
          <CardContent>
            <ul
              data-slot="activity-rings-card-legend"
              className="flex flex-col"
            >
              {rows.map((context) => (
                <li
                  key={context.ring.id}
                  data-slot="activity-rings-card-row"
                  data-ring-id={context.ring.id}
                  data-emphasis={emphasisOf(context.ring.id)}
                  className={cn(
                    ROW_CLASSES,
                    "gap-0.5 border-t border-border py-3 first:border-t-0 first:pt-0 last:pb-0",
                  )}
                  {...rowHandlers(context.ring.id)}
                >
                  <span className="flex items-baseline gap-2">
                    <span className="flex min-w-0 flex-1 items-center gap-2">
                      {swatch(context)}
                      <span className="nessa-text-4 truncate font-medium">
                        {context.ring.label ?? context.ring.id}
                      </span>
                    </span>
                    <span className="nessa-text-4 shrink-0 font-medium tabular-nums">
                      {reading(context)}
                    </span>
                  </span>
                  {context.ring.detail != null ? (
                    <span className="nessa-text-3 truncate pl-4.5 text-muted-foreground">
                      {context.ring.detail}
                    </span>
                  ) : null}
                </li>
              ))}
            </ul>
          </CardContent>
        </>
      )}
    </Card>
  )
}

export { ActivityRingsCard }

/** @responsibility Pure activity-ring geometry: sanitises rings, places them as concentric tracks or as goal-weighted segments of one track, resolves each ring's progress into completed laps plus a leading arc fraction, and draws the track paths. No React, no DOM. */

/** One metric's progress toward its goal. */
export interface ActivityRingInput {
  /** Unique id. */
  id: string
  /**
   * How much has been done. Negative readings are clamped to zero and
   * reported; a non-finite one drops the ring.
   */
  value: number
  /**
   * What counts as complete. Must be positive — a ring with no goal has no
   * progress to show, so it is dropped and reported. In the "segmented"
   * arrangement the goal doubles as the segment's share of the circle, so
   * goals there must share one unit.
   */
  goal: number
}

/**
 * How the rings are placed. "concentric" gives every ring its own full circle,
 * nested outside-in in input order — the Activity-ring form, where a ring can
 * lap its track. "segmented" splits one circle between the rings, each taking
 * a share of the sweep proportional to its goal, and no segment can exceed its
 * own span.
 */
export type ActivityRingsArrangement = "concentric" | "segmented"

/** Inputs the layout is computed from. */
export interface ActivityRingsLayoutOptions {
  rings: readonly ActivityRingInput[]
  /** Pixel width of the area the rings fill. */
  width: number
  /** Pixel height of the area the rings fill. */
  height: number
  arrangement: ActivityRingsArrangement
  /** Band width of a ring, in pixels. */
  thickness: number
  /** Gap between neighbouring concentric tracks, in pixels. */
  ringGap: number
  /** Gap between neighbouring segments, in degrees. Segmented only. */
  segmentGap: number
  /** Where the first ring's track starts, in degrees clockwise from straight up. */
  startAngle: number
}

/** A placed ring. */
export interface ActivityRingsLayoutRing {
  id: string
  /** Index into the original `rings` input. */
  index: number
  /** The reading, clamped to zero at the bottom. */
  value: number
  goal: number
  /** `value / goal`, never clamped at the top — 1.4 means the goal was beaten. */
  progress: number
  /** Radius of the band's centreline. */
  radius: number
  /**
   * Start of the drawn track, in radians clockwise from straight up. A
   * concentric ring's track is the whole circle; a segment's is inset from
   * its share of the circle by the round cap's overhang, so the gap between
   * neighbours is the one the host asked for.
   */
  trackStart: number
  /** End of the drawn track. */
  trackEnd: number
  /**
   * Whole times the ring has already been round its track, drawn as a solid
   * ring beneath the leading arc. Always 0 in the segmented arrangement,
   * where a segment cannot pass its own end.
   */
  laps: number
  /**
   * Fraction of the track the leading arc covers, 0..1. A ring that lands
   * exactly on a whole lap reads as a full arc over one lap fewer, so a
   * completed goal is never drawn as an empty ring.
   */
  fill: number
  /** Angle the leading cap sits at, in radians clockwise from straight up. */
  capAngle: number
}

/**
 * A data problem the layout tolerated instead of failing on. Transient while
 * data streams in; whatever remains once the stream settles is a real data
 * error the host should surface.
 */
export interface ActivityRingsLayoutIssue {
  kind:
    | "duplicate-ring"
    | "invalid-value"
    | "invalid-goal"
    | "no-room"
    | "empty"
  /** Human-readable summary of what was dropped or repaired. */
  message: string
  /** Offending ring id, for ring-scoped issues. */
  ringId?: string
}

/** The computed ring geometry. */
export interface ActivityRingsLayout {
  /** Centre every track is struck from. */
  cx: number
  cy: number
  /** Radius of the outermost band's centreline. */
  outerRadius: number
  /** Radius of the innermost band's centreline. */
  innerRadius: number
  /** Band width the tracks were struck with, after fitting. */
  thickness: number
  /** Largest radius a centred readout can occupy without meeting a band. */
  centerRadius: number
  rings: ActivityRingsLayoutRing[]
  /**
   * Everything the layout dropped or repaired to render this frame — empty
   * when the data was fully consistent.
   */
  issues: ActivityRingsLayoutIssue[]
}

const TAU = Math.PI * 2

function polar(
  cx: number,
  cy: number,
  angle: number,
  distance: number,
): { x: number; y: number } {
  return {
    x: cx + Math.sin(angle) * distance,
    y: cy - Math.cos(angle) * distance,
  }
}

/**
 * Splits `progress` into the whole laps drawn beneath and the leading arc
 * drawn on top. A whole-numbered progress is deliberately read as one lap
 * fewer plus a full arc: taking the remainder literally would draw a met goal
 * as an empty ring, which is the one reading that must never be ambiguous.
 */
function lapsAndFill(progress: number): { laps: number; fill: number } {
  if (!(progress > 0)) return { laps: 0, fill: 0 }
  const whole = Math.floor(progress)
  const remainder = progress - whole
  if (remainder === 0) return { laps: whole - 1, fill: 1 }
  return { laps: whole, fill: remainder }
}

/**
 * Places the rings and resolves each one's progress. Rings are laid outside-in
 * in input order, so the first ring is the outer one and a ring's position
 * keeps naming the same metric however the readings move.
 */
export function computeActivityRingsLayout(
  options: ActivityRingsLayoutOptions,
): ActivityRingsLayout {
  const {
    arrangement,
    ringGap,
    segmentGap,
    startAngle,
    width,
    height,
  } = options
  const issues: ActivityRingsLayoutIssue[] = []

  // Duplicate ids keep their first occurrence so the band, its tint, and its
  // legend row all describe the same input row.
  const seen = new Set<string>()
  const kept: { id: string; index: number; value: number; goal: number }[] = []
  options.rings.forEach((ring, index) => {
    if (seen.has(ring.id)) {
      issues.push({
        kind: "duplicate-ring",
        ringId: ring.id,
        message: `Ring "${ring.id}" appears more than once; the first occurrence was kept.`,
      })
      return
    }
    seen.add(ring.id)
    if (!Number.isFinite(ring.goal) || ring.goal <= 0) {
      issues.push({
        kind: "invalid-goal",
        ringId: ring.id,
        message: `Ring "${ring.id}" has a non-finite or non-positive goal; it was dropped.`,
      })
      return
    }
    if (!Number.isFinite(ring.value)) {
      issues.push({
        kind: "invalid-value",
        ringId: ring.id,
        message: `Ring "${ring.id}" has a non-finite value; it was dropped.`,
      })
      return
    }
    if (ring.value < 0) {
      issues.push({
        kind: "invalid-value",
        ringId: ring.id,
        message: `Ring "${ring.id}" has a negative value; it was read as zero.`,
      })
    }
    kept.push({
      id: ring.id,
      index,
      value: Math.max(0, ring.value),
      goal: ring.goal,
    })
  })

  if (kept.length === 0 && options.rings.length > 0) {
    issues.push({
      kind: "empty",
      message: "No ring carried a usable goal, so nothing was drawn.",
    })
  }

  const cx = width / 2
  const cy = height / 2
  const span = Math.min(width, height)
  const thickness = Math.max(0, Math.min(options.thickness, span / 2))
  const outerRadius = Math.max(0, span / 2 - thickness / 2)
  const step = thickness + Math.max(0, ringGap)
  const origin = (startAngle * Math.PI) / 180

  const rings: ActivityRingsLayoutRing[] = []

  if (arrangement === "concentric") {
    kept.forEach((ring, placement) => {
      const radius = outerRadius - placement * step
      // A band whose centreline has run past the centre would be drawn
      // inside out, so it is dropped rather than folded through itself.
      if (radius < thickness / 2) {
        issues.push({
          kind: "no-room",
          ringId: ring.id,
          message: `Ring "${ring.id}" has no room left at this size; it was dropped.`,
        })
        return
      }
      const progress = ring.value / ring.goal
      const { laps, fill } = lapsAndFill(progress)
      rings.push({
        id: ring.id,
        index: ring.index,
        value: ring.value,
        goal: ring.goal,
        progress,
        radius,
        trackStart: origin,
        trackEnd: origin + TAU,
        laps,
        fill,
        capAngle: origin + TAU * fill,
      })
    })
  } else {
    const totalGoal = kept.reduce((sum, ring) => sum + ring.goal, 0)
    const gap = (Math.max(0, segmentGap) * Math.PI) / 180
    // Every segment is followed by one gap, so the gaps take a fixed bite out
    // of the circle before the goals divide what is left. Gaps wider than the
    // circle would hand the goals a negative sweep and draw every segment
    // backwards, so they collapse instead.
    const available = Math.max(0, TAU - gap * kept.length)
    let cursor = origin
    kept.forEach((ring) => {
      const share = totalGoal > 0 ? ring.goal / totalGoal : 0
      const sweep = available * share
      const progress = ring.value / ring.goal
      // A segment is bounded by its own span: it has nowhere to lap into
      // without painting over its neighbour.
      const fill = Math.min(1, Math.max(0, progress))
      // A round cap overhangs the end of the line it finishes by half the
      // band's width. Drawing the centreline across the segment's whole share
      // would push those two caps into the gaps on either side and close them
      // up, so the drawn track is inset by the overhang and the gap the host
      // asked for is the gap it gets.
      //
      // A share narrower than the band itself has no room for two overhangs.
      // Insetting it by what it cannot spare would collapse the track to
      // nothing and drop the metric off the ring silently, which a lopsided
      // but perfectly valid split — goals of 1 and 99 — reaches immediately.
      // Such a segment instead collapses to a point at the middle of its own
      // share, where the round cap draws it as a dot: the smallest honest
      // mark, still inside the gaps on either side.
      const capReach = outerRadius > 0 ? thickness / outerRadius : 0
      const capInset = sweep > capReach ? capReach / 2 : sweep / 2
      const trackStart = cursor + capInset
      const trackEnd = cursor + sweep - capInset
      // Concentric rings nest outside-in and can run out of room; a segmented
      // set shares one track, so every segment fits whenever the box does.
      rings.push({
        id: ring.id,
        index: ring.index,
        value: ring.value,
        goal: ring.goal,
        progress,
        radius: outerRadius,
        trackStart,
        trackEnd,
        laps: 0,
        fill,
        capAngle: trackStart + (trackEnd - trackStart) * fill,
      })
      cursor += sweep + gap
    })
  }

  const innerRadius = rings.length
    ? Math.min(...rings.map((ring) => ring.radius))
    : outerRadius
  return {
    cx,
    cy,
    outerRadius,
    innerRadius,
    thickness,
    centerRadius: Math.max(0, innerRadius - thickness / 2),
    rings,
    issues,
  }
}

/**
 * The track's centreline as a stroked path, from `startAngle` to `endAngle`
 * clockwise. A full turn is drawn as two half arcs, which one arc command
 * cannot express, and closed so its ends meet without a seam. A zero-length
 * range draws a zero-length subpath rather than nothing, so a round cap still
 * marks the spot.
 *
 * The path carries no fill: stroke it with the band's thickness and a round
 * cap to get the ring.
 */
export function activityRingTrackPath(
  cx: number,
  cy: number,
  radius: number,
  startAngle: number,
  endAngle: number,
): string {
  const sweep = endAngle - startAngle
  if (!(radius > 0) || !Number.isFinite(sweep) || sweep < 0) return ""
  if (sweep === 0) {
    // A zero-length subpath, which a round cap paints as a dot. A segment too
    // narrow to carry two cap overhangs arrives here, and it has to leave a
    // mark: an empty path would take the metric off the ring with nothing to
    // say it was ever there.
    const point = polar(cx, cy, startAngle, radius)
    return `M${point.x},${point.y}L${point.x},${point.y}`
  }
  if (sweep >= TAU - 1e-9) {
    const top = polar(cx, cy, startAngle, radius)
    const bottom = polar(cx, cy, startAngle + Math.PI, radius)
    return `M${top.x},${top.y}A${radius},${radius} 0 0 1 ${bottom.x},${bottom.y}A${radius},${radius} 0 0 1 ${top.x},${top.y}Z`
  }
  const from = polar(cx, cy, startAngle, radius)
  const to = polar(cx, cy, endAngle, radius)
  const large = sweep > Math.PI ? 1 : 0
  return `M${from.x},${from.y}A${radius},${radius} 0 ${large} 1 ${to.x},${to.y}`
}

/**
 * Where the leading cap of a ring's arc sits, for the shadow that separates
 * an overshooting arc from the lap beneath it.
 */
export function activityRingCapPoint(
  ring: Pick<ActivityRingsLayoutRing, "capAngle" | "radius">,
  cx: number,
  cy: number,
): { x: number; y: number } {
  return polar(cx, cy, ring.capAngle, ring.radius)
}
